function nodeStock(n){return Object.entries(n.stock).filter(([p])=>E_RECIPES[n.kind]?[E_RECIPES[n.kind].output,...Object.keys(E_RECIPES[n.kind].inputs)].includes(p):E_PRODUCTS[n.product]?p===n.product:FOOD_RECIPES[n.kind]?[FOOD_RECIPES[n.kind].output,...Object.keys(FOOD_RECIPES[n.kind].inputs)].includes(p):FOOD_PRODUCTS[n.product]?p===n.product:SENSOR.includes(n.kind)?['component','sensor'].includes(p):DIGITAL.includes(n.kind)?['data','service'].includes(p):!FOOD_PRODUCTS[p]&&!['data','service','component','sensor'].includes(p)).map(([p,q])=>PRODUCTS[p].name+' '+q).join(' · ')}
function inspectNode(id){let port=operatingCompany().nodes.find(n=>n.id===id);if(port?.kind==='port')return inspectPort(id);let ad=operatingCompany().nodes.find(v=>v.id===id);if(ad?.kind==='ad')return inspectAd(id);if(ad?.kind==='lab')return inspectLab(id);let n=operatingCompany().nodes.find(v=>v.id===id);if(!n)return;selected={type:'node',id};let incoming=operatingCompany().edges.filter(e=>e.to===id),outgoing=operatingCompany().edges.filter(e=>e.from===id);let stock=nodeStock(n);openSheet('NODE INSPECTOR',`<h2>${KINDS[n.kind].name} <small style="font-size:14px;color:var(--mint)">Lv.${n.level}</small></h2><p>${E_KINDS[n.kind]?eRecipeText(n.kind):FOOD_RECIPES[n.kind]?foodRecipeText(n.kind):n.kind==='supplier'?'정밀부품을 조달합니다. 원료비24 C/개 · 2개/틱. 기존 제조 원료와 분리됩니다.':n.kind==='assembler'?'정밀부품 2 → 산업 센서 1 · 조립 90 C/개. 공정 20% 절감과 별도입니다.':n.kind==='industrial'?'현지 산업 센서를 실제 수요에 납품합니다. 단가180~360 C. 항만/기존매장과 연결하지 않습니다.':n.kind==='collector'?'데이터를 수집합니다. 전력비 8 C/단위. 제조 원료는 소비하지 않습니다.':n.kind==='datacenter'?'데이터 2 → 클라우드 서비스 1 · 전력/연산비 40 C/단위. 제조 효율 연구와 별도입니다.':n.kind==='servicehub'?'클라우드 서비스를 별도 시장 수요에 판매합니다.':n.kind==='mine'?'목재를 채굴합니다. 원료 비용 12 C/개.':n.kind==='factory'?(PRODUCTS[RECIPES[n.product].input].name+' '+RECIPES[n.product].qty+' → '+PRODUCTS[n.product].name+' 1 · 가공 '+Math.round(RECIPES[n.product].cost*(operatingCompany().research.unlocked.includes('process')?.8:1))+' C/개'):'상품: '+PRODUCTS[n.product].name}</p>${eInputs(state,operatingCompany(),n)}<span class="badge" id="node-status">${n.status}</span><div class="row"><small>최대 처리량</small><strong>${capacity(n)}개 / 틱</strong></div><div class="row"><small>고정 운영비</small><strong>${rent(n)} C / 틱</strong></div><div class="row"><small>재고 / 총 ${limit(n)}칸</small></div><p id="node-stock">${stock}</p><p>입력 ${incoming.length}개 · 출력 ${outgoing.length}개 · 드래그로 위치 이동</p>${!sellNode(n)?'<button id="connect-node" class="primary full">출력 연결 → 대상 선택</button>':''}<button id="upgrade-node" class="full" ${n.level>=5?'disabled':''}>설비 증설 · ${fmt(KINDS[n.kind].cost*n.level)} C</button><button id="delete-node" class="danger full">철거 · 60% 기본가 환급</button>`);if(!sellNode(n))$('#connect-node').onclick=()=>setConnecting(id);$('#upgrade-node').onclick=()=>{if(upgradeNode(state,id,operatingCompany())){sound();changed();inspectNode(id);toast('설비 용량을 늘렸습니다')}else toast('현금이 부족하거나 최고 레벨입니다')};$('#delete-node').onclick=()=>{openSheet('DEMOLITION CONFIRM',`<h2>설비를 철거할까요?</h2><p>${KINDS[n.kind].name} 기본가의 60%인 ${fmt(Math.floor(KINDS[n.kind].cost*.6))} C를 돌려받습니다. 증설 비용은 환급되지 않습니다. 재고와 해당 연결선의 운송 중 상품은 폐기되며 이 거래는 되돌릴 수 없습니다.</p><button class="danger full" id="confirm-delete">철거 확정</button><button class="full" id="cancel-delete">취소</button>`);$('#confirm-delete').onclick=()=>{if(b2NodeBusy(state,id))return toast('B2B 배송 중입니다. 다음틱 도착 후 철거하세요');removeNode(state,id,operatingCompany());changed();closeSheet();toast('설비를 철거했습니다')};$('#cancel-delete').onclick=()=>inspectNode(id)}}
function researchCards(){let c=operatingCompany(),r=c.research;return Object.entries(TECHS).map(([id,t])=>{let done=r.unlocked.includes(id),running=r.active?.id===id,missing=t.prereq.filter(k=>!r.unlocked.includes(k)),locked=!done&&!running?(E_TECHS[id]&&state.tick<2700?'전자부품 연구는45분부터':FOOD_RECIPES[id]?null:foodTech(id)&&state.tick<900?'15분부터 연구 가능':['agriculture','baking','dairy','beverage'].includes(id)&&state.tick<900?'농업 연구는15분부터': ['packaging','cloud','precision'].includes(id)?paceError(state,c,id):null):null;return `<article class="tech-card"><small>${done?'✓ 완료':running?'진행 중':locked?'🔒 확장 단계':missing.length?'🔒 선행 필요':'연구 가능'}</small><h3>${t.name}</h3><p>${t.desc}</p>${locked?'<p class="muted">'+esc(locked)+'</p>':''}<div class="row"><small>${fmt(t.cost)} C 일시 지출 · ${t.points} 연구 포인트</small></div><p>${t.prereq.length?'선행: '+t.prereq.map(k=>TECHS[k].name).join(', '):'기초 연구'}${running?'<span id="active-tech-progress"> · '+r.active.progress+' / '+t.points+'P</span>':''}</p><button class="full ${!done&&!missing.length?'primary':''}" data-research="${id}" ${done||running||locked||r.active||missing.length||!c.nodes.some(n=>n.kind==='lab')?'disabled':''}>${done?'완료':running?'연구 진행 중':'연구 시작'}</button></article>`}).join('')}
function bindResearch(){document.querySelectorAll('[data-research]').forEach(b=>b.onclick=()=>{let t=TECHS[b.dataset.research];if(!confirm(t.name+' 연구에 '+fmt(t.cost)+' C를 지출할까요? 연구 완료까지 '+t.points+'포인트가 필요합니다. 도중에 연구소를 철거하면 진행이 멈추고 연구비는 환급되지 않습니다.'))return;let err=startResearch(state,b.dataset.research,operatingCompany());if(err)return toast(err);changed();sound();showResearch()})}
function showResearch(){let c=operatingCompany(),r=c.research,points=Math.min(3,c.nodes.filter(n=>n.kind==='lab').reduce((v,n)=>v+n.level,0));selected={type:'research'};openSheet('RESEARCH & DEVELOPMENT',`<h2>기술을 내 수익으로</h2><p>연구소 레벨 합계당 1P/틱, 회사 합계 최대 3P/틱. 슬롯은 1개입니다. 농업/포장재15분·클라우드30분·정밀센서40분 이후 연구 시작. 선행 기술 → 연구비 → 포인트 완료 → 즉시 적용. 기존 진행 연구와 완료 기술은 보존합니다.</p><span class="badge" id="research-progress">${r.active?TECHS[r.active.id].name+' · '+r.active.progress+'/'+TECHS[r.active.id].points+'P':'진행 중인 연구 없음'}</span><p>현재 ${points}P/틱. 연구소 한빛 유지비1 C/틱은 가공/광고와 별도로 고정비에 포함됩니다. 단일 종이라인보다 여러 생산라인에서 비용절감 연구가 유리합니다. 현금 5,000 C 미만 또는 운영 중단/연구소 없음이면 연구도 멈춥니다. 일시 연구비는 영업이익이 아닌 별도 투자 원장에 기록합니다.</p><div id="research-cards">${researchCards()}</div>`);bindResearch()}
function switchCity(id){if(!operatingCompany().cities.includes(id)){showCityEntry();return;}city=id;$('#rival-grid').dataset.sig='';cancelMode();closeSheet();curves.clear();nodeTiles.clear();particles.forEach(p=>p.active=false);fit();updateUI();}
$('#city-hanbit').onclick=()=>switchCity('hanbit');$('#city-cheolwon').onclick=()=>switchCity('cheolwon');
function showCityEntry(){selected={type:'city-entry'};let locked=paceError(state,operatingCompany(),'city');openSheet('NEW CITY · CHEOLWON PORT',`<h2>철원항에 진출하세요</h2><p>공업·물류 도시. 초기 수요: 종이 2 / 가구 3 / 포장재 4 / 서비스 1 / 센서 1개·틱. 임대·고정비는 한빛의 1.2배(노드별 올림)입니다.</p><p>진출비 12,000 C는 일시 설비 투자입니다. 예비 현금 5,000 C가 필요합니다. 한빛 항만을 먼저 건설하세요. 현지 설비와 양쪽 항만은 별도 건설해야 합니다. 도시 철수·진출비 환급은 이번 범위에 없습니다.</p><p class="muted" id="city-pace">${locked?esc(locked):'45분 확장 단계 충족 · 항만과 예비현금을 확인하세요.'}</p><button id="enter-city" class="primary full" ${locked?'disabled':''}>철원항 진출 · 12,000 C</button>`);$('#enter-city').onclick=()=>{if(!writer)return toast('읽기 전용 탭입니다');if(!confirm('철원항 진출비 12,000 C를 지불할까요? 항만과 현지 설비는 별도이며 진출비는 환급되지 않습니다.'))return;let err=unlockCity(state,'cheolwon',operatingCompany());if(err)return toast(err);changed();switchCity('cheolwon');toast('철원항이 열렸습니다. 현지 항만과 판매망을 건설하세요.');};}
function inspectPort(id){let n=operatingCompany().nodes.find(n=>n.id===id);selected={type:'port',id};let other=operatingCompany().nodes.filter(v=>v.kind==='port'&&cityOf(v)!==cityOf(n)&&v.product===n.product),routes=operatingCompany().edges.filter(e=>{let a=operatingCompany().nodes.find(v=>v.id===e.from),b=operatingCompany().nodes.find(v=>v.id===e.to);return(e.from===id||e.to===id)&&cityOf(a)!==cityOf(b);});openSheet('INTERCITY PORT',`<h2>${CITIES[cityOf(n)].name} · ${PRODUCTS[n.product].name} 항만 Lv.${n.level}</h2><p>한 도시는 한 보드만 표시합니다. 일반 출력 연결은 현지 노드로, 항로 연결은 다른 도시의 같은 상품 항만으로 보냅니다.</p><p id="port-stock">보유 ${n.stock[n.product]}개 · 유지 ${rent(n)} C/틱 · 총 ${limit(n)}칸</p><p>장거리: 6 C/개, 3틱 최소 지연. 한 번에 1개 화물 묶음을 운송하며 도착/재고 여유를 기다립니다. 항로 증설로 묶음 크기를 늘립니다. 디지털 상품과 정밀부품·센서는 실을 수 없습니다.</p>${!operatingCompany().cities.includes('cheolwon')?'<button id="open-city" class="primary full">철원항 진출 안내</button>':''}<button id="port-local" class="full">현지 출력 연결 → 대상 선택</button><select id="remote-port" aria-label="도착 항만">${other.map(v=>`<option value="${v.id}">${CITIES[cityOf(v)].name} 항만 · ${v.id}</option>`).join('')}</select><button id="port-route" class="primary full" ${other.length?'':'disabled'}>선택 항만으로 항로 연결</button>${other.length?'':'<p>도착 도시의 같은 상품 항만을 먼저 건설하세요.</p>'}<div id="port-routes">${routes.map(e=>`<button data-route="${e.id}" class="full">${e.from===id?'출항':'입항'} · 용량 ${e.cap} / 이동 중 ${e.flight}개 · 상세 →</button>`).join('')}</div><button id="port-upgrade" class="full" ${n.level>=5?'disabled':''}>항만 증설 · ${fmt(KINDS.port.cost*n.level)} C</button><button id="port-delete" class="danger full">항만 철거 · 기본가 60% 환급</button>`);if($('#open-city'))$('#open-city').onclick=showCityEntry;$('#port-local').onclick=()=>setConnecting(id);$('#port-route').onclick=()=>{let err=connect(state,id,$('#remote-port').value,operatingCompany());if(err)return toast(err);changed();inspectPort(id);toast('장거리 항로를 연결했습니다');};document.querySelectorAll('[data-route]').forEach(b=>b.onclick=()=>inspectEdge(b.dataset.route));$('#port-upgrade').onclick=()=>{if(upgradeNode(state,id,operatingCompany())){changed();inspectPort(id)}else toast('현금이 부족합니다');};$('#port-delete').onclick=()=>{if(confirm('항만을 철거할까요? 기본가 60% 환급. 모든 연결과 운송 중 상품은 폐기됩니다. 도시 진출과 다른 설비는 남습니다.')){removeNode(state,id,operatingCompany());changed();closeSheet();}};}
function inspectLab(id){let n=operatingCompany().nodes.find(n=>n.id===id);selected={type:'lab',id};openSheet('RESEARCH LABORATORY',`<h2>연구소 Lv.${n.level}</h2><p>기술 트리·신상품·공정/물류 효율을 연구하는 지원 노드입니다. 상품 연결선은 필요하지 않습니다.</p><span class="badge" id="research-progress">${operatingCompany().research.active?TECHS[operatingCompany().research.active.id].name+' 연구 중':'연구 선택 대기'}</span><div class="row"><small>연구 속도</small><strong>${n.level}P/틱 · 회사 합계 최대 3P/틱</strong></div><div class="row"><small>고정비</small><strong>${rent(n)} C/틱</strong></div><button class="primary full" id="open-research">기술 트리 열기</button><button class="full" id="upgrade-lab" ${n.level>=3?'disabled':''}>연구소 증설 · ${fmt(KINDS.lab.cost*n.level)} C</button><button class="danger full" id="delete-lab">연구소 철거</button>`);$('#open-research').onclick=showResearch;$('#upgrade-lab').onclick=()=>{if(upgradeNode(state,id,operatingCompany())){changed();inspectLab(id)}else toast('현금이 부족합니다')};$('#delete-lab').onclick=()=>{if(confirm('연구소를 철거할까요? 기본가의 60% 환급. 다른 연구소가 없으면 연구가 멈추며, 연구비는 환급되지 않습니다. 완료 기술과 진행 포인트는 보존됩니다.')){removeNode(state,id,operatingCompany());changed();closeSheet()}};}
function inspectAd(id){let n=operatingCompany().nodes.find(n=>n.id===id);selected={type:'ad',id};openSheet('BRAND & ADVERTISING',`<h2>광고 대행사</h2><p>${CITIES[cityOf(n)].name} · ${PRODUCTS[n.product].name} 인지도를 쌓아 같은 도시 수요의 배분 가중치를 높입니다. 상품 운송선은 필요하지 않습니다. 품절을 해결하거나 판매를 보장하지 않습니다. 도시·상품별 실제 수요를 누적가중 배분합니다. 한 틱 판매는 0일 수 있으니 최근60틱 평균을 보세요. 예산은 10부터 비교하세요. 25가 더 빨리 회수된다는 보장은 없습니다. 50/100은 작은 시장에서 비용을 회수하지 못할 수 있으며 더 좋은 단계가 아닙니다.</p><div class="row"><small>브랜드 / 100</small><strong id="ad-brand">${(cityBook(operatingCompany(),cityOf(n)).brand[n.product]/100).toFixed(1)}</strong></div><div class="row"><small>판매 가중치</small><strong id="ad-weight">${brandMultiplier(operatingCompany(),n.product,cityOf(n)).toFixed(2)}배</strong></div><div class="row"><small>상품</small><select id="ad-product">${GOODS.filter(p=>(p!=='packaging'||operatingCompany().research.unlocked.includes('packaging'))&&(p!=='service'||operatingCompany().research.unlocked.includes('cloud'))&&(p!=='sensor'||operatingCompany().research.unlocked.includes('precision'))).map(p=>`<option value="${p}" ${n.product===p?'selected':''}>${PRODUCTS[p].name}</option>`).join('')}</select></div><div class="row"><small>광고 예산 / 틱</small><select id="ad-budget">${[0,10,25,50,100].map(v=>`<option value="${v}" ${v===n.budget?'selected':''}>${v?fmt(v)+' C':'광고 일시정지'}</option>`).join('')}</select></div><span class="badge" id="ad-status">${n.status}</span><p>유지비 ${rent(n)} C/틱은 광고를 꺼도 듭니다. 브랜드는 100 상한·체감효과가 있고 시간이 지나면 감소합니다. 같은 상품의 대행사를 더 지어도 총 광고비에 체감효과를 적용합니다. 현금 5,000 C 미만이면 광고비 지출을 자동 중단합니다.</p><p id="ad-spent">최근 광고 지출 ${n.spent} C/틱 · 누적 광고비 ${fmt(operatingCompany().ledger.marketing)} C</p><button id="delete-ad" class="danger full">철거 · 기본가 60% 환급</button>`);$('#ad-budget').onchange=e=>{n.budget=Number(e.target.value);changed();toast('광고 예산을 바꿨습니다')};$('#ad-product').onchange=e=>{n.product=e.target.value;changed();inspectAd(id)};$('#delete-ad').onclick=()=>{if(confirm('대행사를 철거할까요? 기본가의 60%를 환급합니다. 이미 쓴 광고비는 환급되지 않고 쌓인 브랜드는 시간에 따라 감소합니다.')){removeNode(state,id,operatingCompany());changed();closeSheet()}};}
function inspectEdge(id){let e=operatingCompany().edges.find(v=>v.id===id);if(!e)return;selected={type:'edge',id};let n=operatingCompany().nodes.find(n=>n.id===e.from),target=operatingCompany().nodes.find(n=>n.id===e.to);openSheet('LOGISTICS INSPECTOR',`<h2>${PRODUCTS[outProduct(n)].name} ${DIGITAL.includes(n.kind)?'대역폭 연결':'운송선'}</h2><p>${CITIES[cityOf(n)].name} ${KINDS[n.kind].name} → ${CITIES[cityOf(target)].name} ${KINDS[target.kind].name}</p><span class="badge ${e.blocked>=3?'warn':''}">${e.blocked>=3?'! 용량 포화':'정상 전송'}</span><div class="row"><small>운송 용량</small><strong>${e.cap}개 / ${cityOf(n)!==cityOf(target)?'묶음 (3틱)':'틱'}</strong></div><div class="row"><small>최근 운송 / 이동 중</small><strong id="edge-flow">${e.flow} / ${e.flight}개</strong></div><p>운송비 ${shippingCost(operatingCompany(),n,target)} C/개 · 최소 지연 ${cityOf(n)!==cityOf(target)?3:1}틱. ${e.blocked>=3?`출고 대기가 운송 용량을 넘었습니다. 용량을 늘리거나 생산량을 조정하세요.`:'정체가 생기면 노란 선과 ! 표시로 알려드립니다.'}</p><button id="upgrade-edge" class="primary full" ${e.cap>=8?'disabled':''}>용량 ${e.cap*2}개로 증설 · ${fmt(1800*e.cap)} C</button><button id="delete-edge" class="danger full">연결 제거 (운송 중 상품 폐기)</button>`);$('#upgrade-edge').onclick=()=>{if(upgradeEdge(state,id,operatingCompany())){changed();sound();inspectEdge(id);toast('운송 용량을 늘렸습니다')}else toast('현금이 부족하거나 최대 용량입니다')};$('#delete-edge').onclick=()=>{openSheet('REMOVE CONNECTION',`<h2>연결을 제거할까요?</h2><p>운송 중 ${e.flight}개가 폐기됩니다. 운송 증설비는 환급되지 않습니다. 양 끝 노드의 재고는 남습니다.</p><button id="confirm-edge" class="danger full">연결 제거 확정</button>`);$('#confirm-edge').onclick=()=>{operatingCompany().edges=operatingCompany().edges.filter(v=>v.id!==id);changed();closeSheet()}}}
function showBuild(){openSheet('EXPAND YOUR NETWORK',`<h2>흐름을 확장하세요</h2><p>생산할 상품을 정한 뒤 노드를 선택하세요. 보드의 빈 곳을 누르면 건설됩니다. 목재 채굴장은 공용입니다.</p><div class="select-row">${['paper','furniture','packaging'].map(p=>`<button data-product="${p}" class="${buildProduct===p?'chosen':''}" ${p==='packaging'&&!operatingCompany().research.unlocked.includes('packaging')?'disabled':''}>${PRODUCTS[p].name}${p==='packaging'&&!operatingCompany().research.unlocked.includes('packaging')?' 🔒':''}</button>`).join('')}</div><div class="build-grid">${Object.entries(KINDS).filter(([k])=>!DIGITAL.includes(k)&&!SENSOR.includes(k)&&!FOOD_KINDS[k]&&!E_KINDS[k]).map(([k,v])=>`<button data-build="${k}" ${operatingCompany().cash<v.cost?'disabled':''}><b>${v.name}</b><small>${fmt(v.cost)} C · 유지 ${Math.ceil(v.fixed*CITIES[city].rent)} C/틱</small></button>`).join('')}</div>${foodBuildSection()}${eBuildSection(operatingCompany(),{KINDS})}<h2>정밀 센서 산업 ${operatingCompany().research.unlocked.includes('precision')?'':'🔒'}</h2><p>40분부터 정밀 센서 공정 연구. 부품조달소 → 센서조립소 → 산업납품센터를 현지에서 연결하세요. 부품 2개 → 센서 1개, 납품단가 180~360 C. 항만과 기존 제조망에는 연결하지 않습니다.</p><div class="build-grid">${SENSOR.map(k=>`<button data-build="${k}" ${!operatingCompany().research.unlocked.includes('precision')||operatingCompany().cash<KINDS[k].cost?'disabled':''}><b>${KINDS[k].name}</b><small>${fmt(KINDS[k].cost)} C · 유지 ${Math.ceil(KINDS[k].fixed*CITIES[city].rent)} C/틱</small></button>`).join('')}</div><h2>디지털 산업 ${operatingCompany().research.unlocked.includes('cloud')?'':'🔒'}</h2><p>클라우드 연산 연구 후 수집센터 → 연산센터 → 판매 허브를 연결하세요. 제조 물류와 분리된 데이터/서비스 흐름입니다.</p><div class="build-grid">${DIGITAL.map(k=>`<button data-build="${k}" ${!operatingCompany().research.unlocked.includes('cloud')||operatingCompany().cash<KINDS[k].cost?'disabled':''}><b>${KINDS[k].name}</b><small>${fmt(KINDS[k].cost)} C · 유지 ${Math.ceil(KINDS[k].fixed*CITIES[city].rent)} C/틱</small></button>`).join('')}</div><p>권장: 가구 공장 → 가구 창고 → 가구 매장. 채굴장을 추가하거나 기존 채굴장을 분기 연결하세요. 연구소에서 공정/물류 효율과 포장재를 연구할 수 있습니다. 프로토타입 상한 40노드.</p>`);document.querySelectorAll('[data-product]').forEach(b=>b.onclick=()=>{buildProduct=b.dataset.product;showBuild()});document.querySelectorAll('[data-food-build]').forEach(b=>b.onclick=()=>{buildProduct=b.dataset.foodProduct;placing=b.dataset.foodBuild;closeSheet();$('#connect-banner').hidden=false;$('#connect-banner').textContent=KINDS[placing].name+' · '+PRODUCTS[buildProduct].name+' 건설 위치를 누르세요';canvas.style.cursor='crosshair';});document.querySelectorAll('[data-build]').forEach(b=>b.onclick=()=>{placing=b.dataset.build;if(FOOD_PRODUCTS[buildProduct])buildProduct='paper';closeSheet();$('#connect-banner').hidden=false;$('#connect-banner').textContent=KINDS[placing].name+' 건설 위치를 누르세요 · Esc: 취소';canvas.style.cursor='crosshair';toast('보드의 빈 곳을 누르세요')})}
function showNodeList(){openSheet('NETWORK DIRECTORY',`<h2>공급망에서 바로 찾기</h2><p>노드 이름·상품·상태로 찾고 해당 위치로 이동하세요. 줌아웃하면 세부 수치 대신 큰 아이콘으로 표시합니다.</p><input id="node-search" type="search" placeholder="예: 가구, 공장, 원료 부족" aria-label="노드 검색"><div id="node-results"></div>`);function results(){let q=$('#node-search').value.trim().toLowerCase();let ns=visibleNodes().filter(n=>[KINDS[n.kind].name,PRODUCTS[outProduct(n)].name,n.status,n.id].join(' ').toLowerCase().includes(q));let hq=city==='hanbit'&&state.tick>=HQ_UNLOCK&&(!q||'본사 경영 허브 지원'.includes(q));$('#node-results').innerHTML=(hq?'<button id="hq-list-open" class="node-result"><b>본사 경영 허브 <small>무료 지원 표시</small></b><span>생산 설비 수에 포함하지 않음 <i>패널 열기 →</i></span></button>':'')+(ns.length?ns.map(n=>`<button class="node-result" data-jump="${esc(n.id)}"><b>${KINDS[n.kind].name} <small>Lv.${n.level} · ${PRODUCTS[outProduct(n)].name}</small></b><span>${esc(n.status)} · 재고 ${Object.values(n.stock).reduce((a,b)=>a+b,0)} <i>위치로 →</i></span></button>`).join(''):(hq?'':'<p>일치하는 노드가 없습니다.</p>'));if($('#hq-list-open'))$('#hq-list-open').onclick=showHeadquarters;document.querySelectorAll('[data-jump]').forEach(b=>b.onclick=()=>{let n=operatingCompany().nodes.find(n=>n.id===b.dataset.jump);closeSheet();camera.z=Math.max(.95,camera.z);camera.x=W/2-n.x*camera.z;camera.y=Math.max(150,(H-190)/2)-n.y*camera.z;selected={type:'node',id:n.id};toast(KINDS[n.kind].name+' 위치로 이동했습니다')})}$('#node-search').oninput=results;results();}$('#node-list').onclick=showNodeList;
$('#add').onclick=()=>{if(!writer)return toast('다른 탭이 운영 중입니다');cancelMode();showBuild()};
async function openDB(){return openSlotsDB(GAME_ID+':saves');}
async function readSave(key){return readKey(db,key);}
async function save(notify=true,duringTransition=false){if(saveBusy){pendingSave=true;return false;}if(!ready||!writer||!db||settling||offlineBlocked||(slotBusy&&!duringTransition)){if(notify)toast('현재 저장할 수 없습니다. JSON을 내보내세요.');return false;}saveBusy=true;let id=slotId;try{let next=JSON.parse(JSON.stringify(state));next.lastSettledAt=Math.max(next.lastSettledAt,Date.now());validate(next);await writeSlot(db,id,JSON.stringify(next));state.lastSettledAt=next.lastSettledAt;lastSaved=Date.now();if(notify)toast(slotName+' 저장 완료 · 이 브라우저에 보관됩니다');return true;}catch(e){toast('저장 실패 · 원본은 유지됩니다. JSON을 내보내세요.');console.error(e);return false;}finally{saveBusy=false;if(pendingSave){pendingSave=false;queueMicrotask(()=>save(false));}}}
async function writeSettled(next){validate(next);await writeSlot(db,slotId,JSON.stringify(next));}
function offlineReport(){let r=state.offline.lastReport;if(!r)return toast('아직 복귀 정산 기록이 없습니다');let mins=n=>Math.floor(n/60)+'분 '+n%60+'초',row=(k,v)=>`<div class="row"><small>${k}</small><strong>${v}</strong></div>`;openSheet('OFFLINE SETTLEMENT',`<h2>자리를 비운 사이</h2><p>1× 실시간 기준 · 최대8시간 · 동일 경제틱 계산</p>${row('경과 / 반영',mins(r.elapsed)+' / '+mins(r.seconds))}${row('가동 / 안전보류',mins(r.activeSeconds)+' / '+mins(r.safetySeconds))}${row('순현금 변화',(r.cashChange>=0?'+':'')+fmt(r.cashChange)+' C')}${row('매출',fmt(r.ledger.revenue)+' C')}${row('원재료 / 생산',fmt(r.ledger.raw)+' / '+fmt(r.ledger.production)+' C')}${row('운송 / 고정비',fmt(r.ledger.transport)+' / '+fmt(r.ledger.fixed)+' C')}${row('광고 / 전력',fmt(r.ledger.marketing)+' / '+fmt(r.ledger.power)+' C')}${row('설비 / 연구비',fmt(r.ledger.capital)+' / '+fmt(r.ledger.research)+' C')}<p class="muted">금융매수·매도·계약배분도 순현금 변화에 포함됩니다. 대출·이자·채무는 아직 없는 모델입니다.</p>${row(r.shareBasis===60?'시장 점유율(최근60틱)':'시장 점유율(구버전 마지막틱)',r.shareBefore+'% → '+r.shareAfter+'%')}${row('품절 관측',mins(r.stockoutSeconds))}<h3>연구와 안전</h3><p>${r.research.length?r.research.map(id=>esc(TECHS[id]?.name||id)).join(', ')+' 완료':'새 연구 완료 없음'}</p><p>${r.capped?'8시간 초과분은 반영하지 않았습니다.<br>':''}${r.safetySeconds?'안전선 아래에서 생산·운송·판매·고정비·연구를 함께 보류했습니다.<br>':''}${r.risks.map(esc).join('<br>')||'인수·파산 위험 보류 없음'}</p><h3>경쟁사 현금 변화</h3>${r.companies.filter(c=>c.id!=='p').map(c=>row(esc(c.name),(c.after-c.before>=0?'+':'')+fmt(c.after-c.before)+' C')).join('')}<h3>마지막 시장 동향</h3><p>${r.events.map(esc).join('<br>')||'새 동향 없음'}</p><p class="muted">정산 원장을 저장했습니다. 재접속으로 같은 구간을 다시 수령하지 않습니다. 기기 시계 조작은 완전히 막을 수 없습니다.</p><button id="offline-done" class="primary full">보고서 닫기</button>`);$('#offline-done').onclick=closeSheet;}
function offlineWorker(snapshot,now){return new Promise((resolve,reject)=>{let worker=new Worker(new URL('./offline-worker.mjs?v=0.22.0',import.meta.url),{type:'module'}),timer=setTimeout(()=>{worker.terminate();reject(Error('계산시간 초과'))},120000);worker.onmessage=e=>{if(e.data.type==='progress'){$('#offline-progress').textContent=Math.round(e.data.value*100)+'%';return;}clearTimeout(timer);worker.terminate();if(e.data.type==='done')resolve(e.data);else reject(Error(e.data.message));};worker.onerror=e=>{clearTimeout(timer);worker.terminate();reject(Error(e.message||'계산 작업을 시작할 수 없습니다'));};worker.postMessage({state:snapshot,now});});}
async function catchUp(){if(!writer||!db||settling||offlineBlocked||slotBusy||document.hidden||state.finance.loss)return;while(saveBusy)await new Promise(r=>setTimeout(r,10));let now=Date.now(),plan=offlinePlan(state,now);if(plan.clockReversed){toast('기기 시계가 저장시각보다 이전입니다. 경과시간을0으로 처리했습니다.');return;}if(plan.seconds<2)return;settling=true;ready=false;accumulator=0;closeSheet();let overlay=document.createElement('div');overlay.id='offline-overlay';overlay.setAttribute('role','status');overlay.innerHTML='<div><small>OFFLINE SETTLEMENT</small><h2>시장 기록을 계산하는 중</h2><p>생산·재고·경쟁사·지분을 실제 틱으로 정산합니다.<br>저장이 끝날 때까지 이 화면을 열어 두세요.</p><strong id="offline-progress">0%</strong></div>';document.body.append(overlay);try{let result=await offlineWorker(state,now);if(result.report){await writeSettled(result.state);state=result.state;lastSaved=state.lastSettledAt;ready=true;offlineReport();}}catch(e){offlineBlocked=true;toast('복귀 정산 실패: '+e.message+' · 원본 저장은 유지됩니다. 새로고침해 다시 시도하세요.');console.error(e);overlay.innerHTML='<div><small>OFFLINE SETTLEMENT</small><h2>정산을 저장하지 못했습니다</h2><p>원본 저장을 유지했으며 진행을 멈췄습니다.<br>저장공간·비공개모드·작업차단을 확인하고 다시 시도하세요.</p><p id="offline-error"></p><button id="offline-retry" class="primary">새로고침 후 재시도</button> <button id="offline-backup">원본 JSON 보관</button></div>';$('#offline-error').textContent=e.message;$('#offline-retry').onclick=()=>location.reload();$('#offline-backup').onclick=download;}finally{if(!offlineBlocked)overlay.remove();settling=false;ready=true;lastTime=0;accumulator=0;curves.clear();updateUI();}}
function download(){let b=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),a=document.createElement('a'),url=URL.createObjectURL(b);a.href=url;a.download='flow-capital-day'+(Math.floor(state.tick/60)+1)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('저장 파일을 내보냈습니다')}
function showSettings(){openSheet('OPERATIONS SETTINGS',`<h2>운영 설정</h2><p>현재 <b>${esc(slotName)}</b> · 3개 독립 저장</p><button id="slots-open" class="primary full">저장 슬롯 관리</button><p>프로토타입 0.22.0 · 복귀시 최대8시간을 1× 경제틱으로 정산합니다. 생산·비용·AI는 계산하고 인수최종판정·파산·신주발행은 보류합니다. 자동 저장 15초, 슬롯별 최근2세대 보관.</p><div class="row"><small>시각 품질</small><select id="quality"><option value="high" ${settings.quality==='high'?'selected':''}>60fps 목표 · DPR 최대 2</option><option value="low" ${settings.quality==='low'?'selected':''}>30fps 목표 · DPR 최대 1.5</option></select></div><label class="row"><small>상품 이동 효과</small><input id="motion" type="checkbox" ${settings.motion?'checked':''}></label><label class="row"><small>짧은 합성 효과음</small><input id="sound" type="checkbox" ${settings.sound?'checked':''}></label><p>${writer?'이 탭이 운영/저장을 담당합니다.':'다른 탭이 운영 중이므로 이 탭은 읽기 전용입니다. 원래 탭을 닫고 새로고침하세요.'}<br>최근 저장: ${lastSaved?new Date(lastSaved).toLocaleTimeString('ko-KR'):'아직 없음'}.<br>로컬 저장은 기기별입니다. Safari 데이터 정리·비공개 모드·브라우저 삭제 시 사라질 수 있습니다. 중요한 진행은 JSON으로 보관하세요.</p><label class="row"><small>오프라인 현금안전선</small><select id="offline-safety"><option value="0" ${state.offline.safetyCash===0?'selected':''}>0 C</option><option value="5000" ${state.offline.safetyCash===5000?'selected':''}>5,000 C</option><option value="10000" ${state.offline.safetyCash===10000?'selected':''}>10,000 C</option><option value="20000" ${state.offline.safetyCash===20000?'selected':''}>20,000 C</option></select></label><p class="muted">안전선 아래에서는 내 회사와 자회사의 생산·판매·비용·연구를 함께 멈춥니다. 0 C도 임대료가 부족하면 가동을 멈춥니다. 온라인에서는 이 설정이 적용되지 않습니다.</p><button id="offline-last" class="full">최근 복귀 보고서</button><button id="export" class="full">JSON 내보내기</button><button id="import" class="full" ${!writer?'disabled':''}>JSON 가져오기</button><button id="recover" class="full" ${!writer?'disabled':''}>이전 자동 저장 복구</button><button id="restart" class="danger full" ${!writer?'disabled':''}>새 회사 시작</button>`);$('#slots-open').onclick=showSlots;$('#offline-safety').disabled=!writer;$('#offline-safety').onchange=e=>{if(!writer)return;state.offline.safetyCash=Number(e.target.value);save(false)};$('#offline-last').onclick=offlineReport;$('#quality').onchange=e=>{settings.quality=e.target.value;rememberSettings()};$('#motion').onchange=e=>{settings.motion=e.target.checked;rememberSettings()};$('#sound').onchange=e=>{settings.sound=e.target.checked;rememberSettings();sound()};$('#export').onclick=download;$('#import').onclick=()=>{importTarget=slotId;$('#import-file').click()};$('#recover').onclick=async()=>{if(!writer||!confirm(slotName+'의 이전 저장으로 복구할까요?'))return;try{let slot=await readSlot(db,slotId);if(!slot.previous)throw Error('이전 저장이 없습니다');await replaceActive(migrate(JSON.parse(slot.previous)));}catch(e){toast('복구 실패: '+e.message)}};$('#restart').onclick=async()=>{if(!writer||!confirm(slotName+'의 현재 진행을 새 회사로 바꿀까요? JSON 보관을 권합니다.'))return;await replaceActive(createGame());}}

$('#import-file').onchange=async e=>{let f=e.target.files[0],target=importTarget||slotId;importTarget=null;e.target.value='';if(!f||!writer)return;if(f.size>2e6)return toast('파일은2MB 이하여야 합니다');try{let next=migrate(JSON.parse(await f.text()));let targetSlot=await readSlot(db,target);if(!confirm(targetSlot.name+'에 이 파일을 가져올까요? 기존 진행은 이전 세대로 보관됩니다.'))return;if(target===slotId)await replaceActive(next);else{if(slotBusy)return;slotBusy=true;try{await waitStorage();await uniqueCampaign(next,target);if(!await save(false,true))return;await writeSlot(db,target,JSON.stringify(next),{replace:true});toast(targetSlot.name+' 가져오기 완료');await showSlots();}finally{slotBusy=false;}}}catch(e){toast('가져오기 실패 · 원본 유지: '+e.message)}};

$('#save').onclick=()=>save();$('#menu').onclick=showSettings;$('#pause').onclick=()=>{paused=!paused;$('#pause').textContent=paused?'▶':'Ⅱ';$('#pause').setAttribute('aria-label',paused?'계속':'일시정지')};$('#speed').onclick=()=>{speed=speed===1?2:speed===2?4:1;$('#speed').textContent=speed+'×'};
function switchTab(t){if(t==='finance'){companyId='p';if(!state.player.cities.includes(city))city='hanbit';}active=t;document.body.dataset.view=t;closeSheet();cancelMode();document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active',v.id===t));document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===t));syncCompact();if(t==='network'){renderSignature='';resize();}updateUI()}
