function updateRivals(){let list=rivals(state),filtered=list.filter(c=>rivalFilter==='all'||rivalFilter==='closed'?rivalFilter!=='closed'||c.status!=='active':c.tier===rivalFilter);$('#rival-summary').textContent='전체 '+list.length+'개 · 메이저 '+list.filter(c=>c.tier==='major'&&c.status==='active').length+' · 마이너 '+list.filter(c=>c.tier==='minor'&&c.status==='active').length+' · 도산/인수 '+list.filter(c=>c.status!=='active').length;let sig=filtered.map(c=>c.id+':'+c.tier+':'+c.status).join('|');if($('#rival-grid').dataset.sig!==sig){$('#rival-grid').dataset.sig=sig;$('#rival-grid').innerHTML=filtered.map(c=>`<article class="competitor-card"><div class="competitor-title"><b>${esc(c.name)}</b><span>${TIERS[c.tier]}</span></div><p>${STYLES[c.style]} · 시작 현금 ${fmt(c.initialCash)} C</p><span class="badge" id="rs-${c.id}"></span><div class="row"><small>현금</small><strong id="rc-${c.id}"></strong></div><div class="row"><small>최근 영업이익</small><strong id="rp-${c.id}"></strong></div><div class="row"><small>${CITIES[city].name} 판매량 / 틱</small><strong id="rv-${c.id}"></strong></div><small id="rn-${c.id}"></small><button class="full" data-rival="${c.id}">회사 상세 →</button></article>`).join('');document.querySelectorAll('[data-rival]').forEach(b=>b.onclick=()=>showRival(b.dataset.rival));}for(let c of filtered){$('#rs-'+c.id).textContent=c.status==='bankrupt'?'도산 · 영업 중단':c.status==='acquired'?'인수 · 독립 전략 중지':state.tick<c.activationTick?'진입 대기 · '+Math.ceil((c.activationTick-state.tick)/60)+'일 뒤 영업':'영업 중';$('#rc-'+c.id).textContent=fmt(c.cash)+' C';$('#rp-'+c.id).textContent=(c.last.profit>=0?'+':'')+fmt(c.last.profit)+' C';$('#rv-'+c.id).textContent=Object.values(cityBook(c,city).sales).reduce((t,v)=>t+v,0)+'개';$('#rn-'+c.id).textContent=c.cities.map(id=>CITIES[id].name).join(' · ')+' / '+c.nodes.length+'설비 · '+c.edges.length+'연결';}let newsSig=state.logs.map(l=>l.tick+l.text).join('|');if($('#news').dataset.sig!==newsSig){$('#news').dataset.sig=newsSig;$('#news').innerHTML=state.logs.map(l=>`<div class="news-item"><small>DAY ${Math.floor(l.tick/60)+1}</small><span>${esc(l.text)}</span></div>`).join('');}}
function showRival(id){let c=rivals(state).find(c=>c.id===id);selected={type:'rival',id};openSheet('COMPANY INTELLIGENCE',`<h2>${esc(c.name)}</h2><span class="badge">${TIERS[c.tier]} · ${STYLES[c.style]}</span><p>초기 현금 ${fmt(c.initialCash)} C. 초기 설비/해금은 시작 자산이며, 이후 설비·광고·연구·진출은 실제 원장으로 지불합니다. 신규 한빛 경쟁은 1,800틱까지 대기하며, 기존 저장에 추가된 회사는 최소600틱 유예입니다. 대기 중에는 생산·판매·비용·전략이 멈춥니다.</p><div class="row"><small>현금 / 영업이익</small><strong id="rival-finance">${fmt(c.cash)} / ${fmt(c.last.profit)} C</strong></div><p>메이저: 성격별 가격/광고/연구/확장. 마이너: 가격·생산과 제한적 물류 개선. 영업이익 80,000 C, 현금65,000 C, 업력1,800틱을 모두 채우면 메이저 자리 최대4개까지 승격합니다.</p><p>180틱 연속 비용 지급 불가 시 도산합니다. 도산 회사 자산/원장은 보존되고 영업은 멈춥니다. 3,600틱마다 빈자리가 있으면 새 창업자 자본으로 마이너가 진입합니다. 전체 기록은 최대12개입니다. 금융탭에서 지분·공개매수·자회사를 관리합니다.</p><h3>선택 도시 · ${CITIES[city].name}</h3><div id="rival-products">${GOODS.map(p=>`<div class="row"><small>${PRODUCTS[p].name}</small><strong>${cityBook(c,city).price[p]} C · 판매 ${cityBook(c,city).sales[p]}</strong></div>`).join('')}</div><p>성격·계급은 전략 차이이며 무료 수익/수요 보너스가 아닙니다. 기업 네트워크는 화면에 그리지 않습니다. 금융탭의 지분/경보를 함께 확인하세요.</p>`);}
$('#rival-filter').onchange=e=>{rivalFilter=e.target.value;$('#rival-grid').dataset.sig='';updateRivals();};
const pct=n=>(100*n).toFixed(1)+'%';
function financeReview(title,q,execute,again){if(q.error)return toast(q.error);openSheet('FINANCIAL TRANSACTION REVIEW',`<h2>${title}</h2><p>게임 내 크레딧 거래입니다. 경제 거래는 편집 되돌리기로 취소할 수 없습니다.</p><div class="row"><small>수량</small><strong>${q.quantity}주</strong></div><div class="row"><small>금액/수수료</small><strong>${fmt(q.gross)} / ${fmt(q.fee)} C</strong></div><div class="row"><small>현금 변화</small><strong>${q.net!==undefined?'+ '+fmt(q.net):q.side==='sell'?'+ '+fmt(q.total):'− '+fmt(q.total)} C</strong></div><div class="row"><small>보유 비율</small><strong>${pct(q.before)} → ${pct(q.after)}</strong></div>${(q.attackers||[]).map(a=>`<p class="warn">${esc(a.name)} ${pct(a.before)} → ${pct(a.after)}${a.after>a.before?' · 소각이 공격자비율을 높입니다':' · 희석됩니다'}</p>`).join('')}${q.expiresTick?'<p>신주10%할인 ·30게임일 계약 ·계약중 양의일영업이익×우호지분율×10%를 회사현금에서 배분합니다. 계약종료5일전 예고하고 종료뒤 일반주주로 남습니다. 무료/영구 우호가 아닙니다.</p>':''}<p>${q.settleTick?'다음 게임일 '+(Math.ceil(q.settleTick/60)+1)+'에 체결합니다. 매수대금은 지금 예약하고 체결 불가면 환급합니다.':'발행/소각은 확인 후 바로 반영됩니다.'}</p><button id="finance-confirm" class="primary full">거래 확정</button><button id="finance-cancel" class="full">돌아가기</button>`);$('#finance-confirm').onclick=()=>{if(!writer||state.finance.loss)return toast('현재 거래할 수 없습니다');let latest=again();if(latest.error)return toast(latest.error);if(JSON.stringify(latest)!==JSON.stringify(q)){toast('조건이 바뀌었습니다. 새 금액을 확인하세요.');return financeReview(title,latest,execute,again);}let err=execute();if(err)return toast(err);changed();closeSheet();toast('금융 거래를 기록했습니다');};$('#finance-cancel').onclick=()=>{closeSheet();updateFinance();};}
function updateFinance(){let c=state.player,e=c.equity,rows=companies(state);let sig=rows.map(c=>c.id+':'+c.equity.listed+':'+c.status).join('|');if($('#finance-list').dataset.sig!==sig){$('#finance-list').dataset.sig=sig;$('#finance-list').innerHTML=rows.map(c=>`<article class="competitor-card"><div class="competitor-title"><b>${esc(c.name)}</b><span>${c.equity.listed?'상장':'비상장'}</span></div><div class="row"><small>주가 / 시가총액</small><strong id="fq-${c.id}"></strong></div><div class="row"><small>내 회사 보유 / 유통</small><strong id="fh-${c.id}"></strong></div><button class="full" data-equity="${c.id}">지분 상세·주문 →</button></article>`).join('');document.querySelectorAll('[data-equity]').forEach(b=>b.onclick=()=>showEquity(b.dataset.equity));}for(let r of rows){let eq=r.equity;$('#fq-'+r.id).textContent=fmt(eq.price)+' / '+fmt(eq.price*eq.total)+' C';$('#fh-'+r.id).textContent=(eq.holders[c.id]||0)+' / '+(eq.holders.public||0)+'주';}$('#own-equity').textContent=(e.listed?'상장':'비상장')+' · 창업자 '+pct((e.holders['founder:'+c.id]||0)/e.total)+' · 총 '+e.total+'주 · 누적 금융 현금변화 '+fmt(c.ledger.finance)+' C';let orderSig=state.finance.orders.map(o=>o.id).join('|');if($('#stock-orders').dataset.sig!==orderSig){$('#stock-orders').dataset.sig=orderSig;$('#stock-orders').innerHTML=state.finance.orders.filter(o=>o.owner===c.id).map(o=>`<article class="tech-card"><b>${esc(companies(state).find(c=>c.id===o.target).name)} ${o.side==='buy'?'매수':'매도'} ${o.quantity}주</b><p>체결 예정 DAY ${Math.ceil(o.settleTick/60)+1} · 예약금 ${fmt(o.reserved)} C · 가격 ${o.price} C</p><button data-order-cancel="${o.id}" class="full">미체결 주문 취소</button></article>`).join('')||'<p class="muted">미체결 주문 없음</p>';document.querySelectorAll('[data-order-cancel]').forEach(b=>b.onclick=()=>{if(!writer)return;let err=cancelOrder(state,b.dataset.orderCancel);if(err)return toast(err);changed();});}}
function showEquity(id){selected={type:'equity',id};let c=companies(state).find(c=>c.id===id),e=c.equity;openSheet('SHARE LEDGER',`<h2>${esc(c.name)} ${e.listed?'상장':'비상장'}</h2><p>주가 ${fmt(e.price)} C · 총 ${e.total}주 · 시가총액 ${fmt(e.total*e.price)} C</p><p>최근 ${e.profitDays.length}일 평균 영업이익 ${fmt(Math.round(e.profitDays.reduce((a,v)=>a+v,0)/Math.max(1,e.profitDays.length)))} C/일. 게임용 가치평가이며 거래가격/수익은 보장하지 않습니다.</p>${Object.entries(e.holders).filter(([_,v])=>v>0).map(([owner,n])=>`<div class="row"><small>${owner==='public'?'대중':owner==='friendly'?'우호투자자':owner.startsWith('founder:')?'창업자':esc(companies(state).find(c=>c.id===owner)?.name||owner)}</small><strong>${n}주 · ${pct(n/e.total)}</strong></div>`).join('')}<p>채무0 C·인재/임대계약모델 없음. 직접지분20%/35% 경보, 최소5일 대응 뒤50%초과만 인수입니다. 자회사 자산/현금·소수주주는 별도 회사원장에 보존합니다. 월간 AI 공격·방어3종·피인수 결과가 작동합니다. 자동 방어는 플레이어에게 적용하지 않습니다.</p>${c.id!==state.player.id&&e.listed&&c.status==='active'?'<label class="row"><small>주문 수량</small><input id="stock-quantity" type="number" min="1" max="100" value="5"></label><button id="stock-buy" class="primary full">매수 검토</button><button id="stock-sell" class="full">매도 검토</button>':''}${c!==state.player&&['active','acquired'].includes(c.status)&&(!c.controller||c.controller===state.player.id)?'<button id="tender-open" class="primary full">'+(e.listed?'공개매수':'비상장 협상매수')+' 조건 설정</button>':''}<p>일 주문한도 총주식의10%, 매수/매도 대중 유통·보유량 내. 매도대금은 매도자에게 가며 발행회사 현금은 늘지 않습니다. 수수료2%와 수량별 가격충격이 있습니다. 창업자 주식 자동매도·공매도·순환출자는 금지합니다.</p>`);if($('#stock-buy')){for(let side of ['buy','sell'])$('#stock-'+side).onclick=()=>{let quantity=Number($('#stock-quantity').value);let again=()=>quoteTrade(state,id,side,quantity);financeReview(c.name+' '+(side==='buy'?'매수':'매도'),again(),()=>placeOrder(state,id,side,quantity),again);};}if($('#tender-open'))$('#tender-open').onclick=()=>showTender(id);}
