function showTender(id){selected={type:'tender',id};let c=companies(state).find(c=>c.id===id),e=c.equity,locked=paceError(state,state.player,'acquire')||(state.tick<c.activationTick?'진입 보호 중인 회사는 매수할 수 없습니다':null);openSheet('TENDER OFFER · GAME CREDITS',`<h2>${esc(c.name)} ${e.listed?'공개매수':'협상매수'}</h2><p>최근주가 ${fmt(e.price)} C. 대중은 프리미엄에 따라 응모,AI 창업자는20%(기술선점25%) 이상 프리미엄에서 응모합니다. 체결일의 주가에 따라 달라집니다. 내 창업자주식은 자동 응모하지 않습니다.</p><label class="row">제시가 / 주 <input id="tender-price" type="number" min="1" value="${Math.ceil(e.price*1.3)}"></label><label class="row">목표수량 <input id="tender-quantity" type="number" min="1" value="${Math.min(e.total-(e.holders.p||0),Math.floor(e.total*.65))}"></label><label class="row">기간 / 게임일 <input id="tender-days" type="number" min="5" max="20" value="5"></label><p>응모초과 비례배분·미달 부분체결·잔액환급. 자회사우회매집·순환출자 금지. 공개경보 후 최소5일,최종직접지분50%초과일 때만 지배권을 얻습니다.</p><p class="muted" id="tender-pace">${locked?esc(locked):'70분 확장 단계 충족 · 실제 견적과 응모 위험을 확인하세요.'}</p><button id="tender-review" class="primary full" ${locked?'disabled':''}>최대대금·통합손익 검토</button>`);$('#tender-review').onclick=()=>{let price=Number($('#tender-price').value),quantity=Number($('#tender-quantity').value),days=Number($('#tender-days').value),again=()=>quoteTender(state,id,price,quantity,days);let q=again();if(q.error)return toast(q.error);openSheet('TAKEOVER REVIEW',`<h2>${esc(c.name)} 매수 검토</h2><div class="row"><small>최대 예약 / 수수료</small><strong>${fmt(q.total)} / ${fmt(q.fee)} C</strong></div><div class="row"><small>수량·가격·기간</small><strong>${q.quantity}주 · ${fmt(q.price)} C · ${q.days}일</strong></div><div class="row"><small>지분: 전 → 전량체결시</small><strong>${pct(q.before)} → ${pct(q.after)}</strong></div><p>현재 예상응모 ${tenderForecast(state,{target:id,owner:'p',price})}주 (확정 아님). 응모/주가 변화로 과반에 실패할 수 있습니다. 매수대금은 주주에게 가고 대상회사현금은 늘지 않습니다.</p><p>대상 설비 ${q.nodes}개 · 회사현금 ${fmt(q.targetCash)} C 별도보존 · 최근영업이익 ${fmt(q.operating)} C/틱. 전량체결시 본사+대상 지분배분 추정영업이익 ${fmt(Math.round(groupProfit(state)+q.operating*(q.after-q.before)))} C/틱. 채무0 C: 부채/인재·임대계약은 미구현입니다. 설비·기술·브랜드를 새로 복제하지 않으며 성공해도 현재점유율은 보장되지 않습니다.</p><button id="tender-confirm" class="primary full">최대대금 예약·매수 개시</button>`);$('#tender-confirm').onclick=()=>{if(!writer)return;let latest=again();if(latest.error)return toast(latest.error);if(JSON.stringify(latest)!==JSON.stringify(q)){toast('조건이 바뀌었습니다. 다시 검토하세요');return showTender(id);}let err=openTender(state,id,price,quantity,days);if(err)return toast(err);changed();closeSheet();};};}
function updateTakeovers(){let f=state.finance,sig=f.tenders.map(t=>t.id).join('|')+'|'+Object.entries(f.alerts).map(([id,a])=>id+a.owner+a.level).join('|')+'|'+f.takeoverHistory.map(t=>t.tick+t.target+t.kind).join('|');if($('#takeover-list').dataset.sig!==sig){$('#takeover-list').dataset.sig=sig;$('#takeover-list').innerHTML=f.tenders.map(t=>`<article class="tech-card"><b>${esc(companies(state).find(c=>c.id===t.target).name)} 매수 진행 · ${t.quantity}주</b><p>예약 ${fmt(t.reserved)} C · 종료 DAY ${Math.floor(t.endsTick/60)+1}. 체결 시 응모수량과 잔액을 정산합니다.</p><button data-tender-cancel="${t.id}" class="full">공개매수 취소·전액환급</button></article>`).join('')+Object.entries(f.alerts).map(([id,a])=>`<article class="tech-card"><b>${esc(companies(state).find(c=>c.id===id).name)} ${a.level}% 경보</b><p>지배권 판정 가능 DAY ${Math.floor(a.deadline/60)+1} 이후 ·50%초과 필요. 정확히50%는 실패.</p></article>`).join('')+f.takeoverHistory.slice(0,5).map(t=>`<p class="muted">${esc(companies(state).find(c=>c.id===t.target).name)} · ${t.kind==='control'?'지배권 확보':t.quantity+'주 체결 · '+fmt(t.refund)+' C 환급'} · DAY ${Math.floor(t.tick/60)+1}</p>`).join('');document.querySelectorAll('[data-tender-cancel]').forEach(b=>b.onclick=()=>{if(!writer)return;let err=cancelTender(state,b.dataset.tenderCancel);if(err)return toast(err);changed();});}let group=groupCompanies(state).filter(c=>c!==state.player),gsig=group.map(c=>c.id).join('|');if($('#subsidiary-list').dataset.sig!==gsig){$('#subsidiary-list').dataset.sig=gsig;$('#subsidiary-list').innerHTML=group.map(c=>`<article class="competitor-card"><b>${esc(c.name)} · 자회사</b><p>직접보유 ${c.equity.holders.p||0}/${c.equity.total}주 · 소수주주 보존. 회사선택에서 생산망/가격/연구를 관리합니다. 현금은 별도이며 자산을 본사로 복제하지 않습니다.</p><label class="row">재무이체 C <input id="treasury-${c.id}" type="number" min="1" value="1000"></label><button data-treasury="${c.id}" class="full">본사 → 자회사 이체 검토</button><button data-return="${c.id}" class="full">자회사 → 본사 이체 검토</button></article>`).join('')||'<p class="muted">지배 자회사 없음</p>';for(let direction of ['treasury','return'])document.querySelectorAll('[data-'+direction+']').forEach(b=>b.onclick=()=>{let id=b.dataset[direction],amount=Number($('#treasury-'+id).value);if(!writer||!Number.isSafeInteger(amount)||amount<1)return toast('1 C 이상 정수를 선택하세요');if(!confirm(companies(state).find(c=>c.id===id).name+'와 '+fmt(amount)+' C '+(direction==='treasury'?'본사→자회사':'자회사→본사')+' 재무이체를 할까요? 영업이익이 아니며 소수주주가 있는 회사의 현금도 변합니다.'))return;let err=transferTreasury(state,id,amount,direction==='treasury');if(err)return toast(err);changed();});}}
let lossShown=false,checkpointKey='',checkpointBusy=false;
async function checkpointDefense(){let a=state.finance.alerts.p;if(!db||!writer||!a||state.finance.loss||slotBusy)return;let key=slotId+':'+state.campaignId+':'+a.owner+':'+a.startedTick;if(key===checkpointKey||checkpointBusy)return;checkpointBusy=true;let id=slotId;try{let txt=JSON.stringify(state);validate(JSON.parse(txt));await writeCheckpoint(db,id,txt);checkpointKey=key;}catch{toast('방어 복구 저장 실패. JSON을 내보내세요.');}finally{checkpointBusy=false;}}

function showLoss(){paused=true;$('#pause').textContent='▶';if(lossShown&&$('#loss-restore'))return;lossShown=true;let result=state.finance.loss,owner=companies(state).find(c=>c.id===result.owner);openSheet('CONTROL LOST · GAME RESULT',`<h2>내 회사 지배권을 잃었습니다</h2><p>${esc(owner.name)} 직접지분 ${pct(result.ratio)}. 공개경보 이후 최소5게임일이 끝나 지배권을 판정했습니다. 창업자 ${state.player.equity.holders['founder:p']||0}주는 자동매도하지 않았습니다. 회사/소수주주/설비원장은 남으며 진행은 여기서 멈춥니다.</p><button id="loss-restore" class="primary full">최근 방어 체크포인트 복구</button><button id="loss-export" class="full">결과 JSON 내보내기</button><button id="loss-slots" class="full">다른 저장 슬롯 열기</button><button id="loss-restart" class="danger full">새 회사 시작</button><p>복구 저장이 없으면 새 회사 또는 보관한 JSON을 사용하세요. 장기 오프라인 정산은 아직 없으며 별도 러너의 최종판정 보류 훅만 준비했습니다.</p>`);$('#close').hidden=true;$('#loss-restore').onclick=async()=>{if(!writer)return;try{let txt=await readSave('defensecheckpoint');if(!txt)txt=await readSave('previous');if(!txt)throw Error('정상 복구 저장 없음');let recovered=migrate(JSON.parse(txt));if(recovered.campaignId!==state.campaignId)throw Error('다른 회사의 복구 저장입니다');if(recovered.finance.loss)throw Error('이전 저장도 지배권 상실 상태');if(await replaceActive(recovered)){paused=true;toast('방어 시점 복구. 일시정지 상태에서 방어를 선택하세요.');}}catch(e){toast('복구 불가: '+e.message);}};$('#loss-export').onclick=download;$('#loss-slots').onclick=showSlots;$('#loss-restart').onclick=async()=>{if(!writer||!confirm('현재 회사 대신 새 회사를 시작할까요?'))return;await replaceActive(createGame());paused=true;};}
