$('#poison-review').onclick=()=>{let q=quotePoison(state);if(q.error)return toast(q.error);openSheet('RIGHTS PLAN REVIEW',`<h2>사전 유료 포이즌필</h2><p>회사현금1200 C로1회 계획을 설정합니다. 공격자직접지분35%에서 다른주주가 주가30%할인으로 자기현금을 내고 신주를 받습니다. 내 창업자개인현금0이면 행사할 수 없습니다. 대중/우호/다른회사도 실제현금이 있어야 합니다.</p><p>최대 ${q.maxShares}주,한주주당 기존보유주 이하·총주식100000주상한. 발동후1800틱 쿨다운·모든도시브랜드5%하락. 돈이 없어0주만 행사돼도 발동을 소모합니다. 희석·평판비용이 있고 방어성공을 보장하지 않습니다.</p><button id="poison-confirm" class="primary full">1200 C 지출·권리계획 설정</button>`);$('#poison-confirm').onclick=()=>{if(!writer||state.finance.loss)return;let err=armPoison(state);if(err)return toast(err);changed();closeSheet();};};
function drawChart(){let cv=$('#chart'),r=cv.getBoundingClientRect();if(!r.width)return;cv.width=r.width*DPR;cv.height=150*DPR;let c=cv.getContext('2d');c.scale(DPR,DPR);let h=operatingCompany()===state.player?state.history:[];if(!h.length){c.fillStyle='#8499b1';c.font='12px sans-serif';c.fillText('첫날 마감 후 기록이 나타납니다.',20,80);return;}let min=Math.min(0,...h.map(v=>v.profit)),max=Math.max(100,...h.map(v=>v.profit)),y=v=>125-(v-min)/(max-min)*95;c.strokeStyle='#2a3b50';c.beginPath();c.moveTo(15,y(0));c.lineTo(r.width-15,y(0));c.stroke();c.strokeStyle='#5de1ca';c.lineWidth=2;c.beginPath();h.forEach((v,i)=>{let x=20+i*(r.width-40)/Math.max(1,h.length-1);i?c.lineTo(x,y(v.profit)):c.moveTo(x,y(v.profit))});c.stroke();c.fillStyle='#5de1ca';h.forEach((v,i)=>{c.beginPath();c.arc(20+i*(r.width-40)/Math.max(1,h.length-1),y(v.profit),3,0,Math.PI*2);c.fill()});c.font='10px monospace';c.fillStyle='#8499b1';c.fillText('영업이익 / C   최근 '+h.length+'일',18,20);}
const NODE_W=182,NODE_H=134,kindColors={...Object.fromEntries(Object.keys(E_KINDS).map(k=>[k,'#80bce3'])),...Object.fromEntries(Object.keys(FOOD_KINDS).map(k=>[k,['wheatfarm','dairyfarm','grapefarm'].includes(k)?'#a6cf87':'#e4b37a'])),supplier:'#f5ce68',assembler:'#f1ab68',industrial:'#f8e6a6',port:'#6ad8ee',collector:'#80bfff',datacenter:'#c698ff',servicehub:'#9ebaff',mine:'#cda978',factory:'#5de1ca',warehouse:'#82b9ee',store:'#e9b671',ad:'#d6a4f4',lab:'#92a3ff'};
function mobilePositions(){if(innerWidth<650&&state.tick===0&&operatingCompany().edges.length===0){let pts=[[120,150],[350,150],[350,360],[120,360]];operatingCompany().nodes.forEach((n,i)=>{if(pts[i])[n.x,n.y]=pts[i]})}}
function resize(){let r=canvas.getBoundingClientRect();if(!r.width||!r.height)return;if(W&&H){camera.x+=(r.width-W)/2;camera.y+=(r.height-H)/2;}W=r.width;H=r.height;DPR=Math.min(devicePixelRatio||1,settings.quality==='low'?1.5:2);canvas.width=Math.round(W*DPR);canvas.height=Math.round(H*DPR);icons.clear();nodeTiles.clear();badgeCache.clear();if(firstFit){fit();firstFit=false}}
function fit(){let ns=visibleNodes();if(!ns.length){camera.z=innerWidth<650?.45:.8;camera.x=W/2-470*camera.z;camera.y=80;return}let l=Math.min(...ns.map(n=>n.x))-110,r=Math.max(...ns.map(n=>n.x))+110,t=Math.min(...ns.map(n=>n.y))-90,b=Math.max(...ns.map(n=>n.y))+90;let mobile=innerWidth<650,hq=city==='hanbit'&&state.tick>=HQ_UNLOCK,short=innerHeight<=480&&innerWidth<=950,top=short?64:mobile?(hq?142:124):(hq?155:80),bottom=short?68:mobile?190:180,areaH=Math.max(1,H-top-bottom);camera.z=clamp(Math.min((W-32)/(r-l),areaH/(b-t)),.15,1.2);camera.x=W/2-(l+r)/2*camera.z;camera.y=top+areaH/2-(t+b)/2*camera.z;}
function zoom(f,x=W/2,y=(H-150)/2){let z=clamp(camera.z*f,.15,2.2),ratio=z/camera.z;camera.x=x-(x-camera.x)*ratio;camera.y=y-(y-camera.y)*ratio;camera.z=z}
$('#fit').onclick=fit;$('#zoomin').onclick=()=>zoom(1.2);$('#zoomout').onclick=()=>zoom(1/1.2);addEventListener('resize',()=>{resize();if((innerWidth<650)!==oldSmall){oldSmall=innerWidth<650;fit()}});
function round(c,x,y,w,h,r){c.beginPath();if(c.roundRect){c.roundRect(x,y,w,h,r);return;}r=Math.max(0,Math.min(r,w/2,h/2));c.moveTo(x+r,y);c.lineTo(x+w-r,y);c.quadraticCurveTo(x+w,y,x+w,y+r);c.lineTo(x+w,y+h-r);c.quadraticCurveTo(x+w,y+h,x+w-r,y+h);c.lineTo(x+r,y+h);c.quadraticCurveTo(x,y+h,x,y+h-r);c.lineTo(x,y+r);c.quadraticCurveTo(x,y,x+r,y);c.closePath();}
