function drawMinimap(){if(!miniOpen||!W||!H)return;let ns=visibleNodes(),width=190,height=120,dpr=Math.min(2,DPR),signature=operatingCompany().id+'|'+city+'|'+dpr+'|'+ns.map(n=>[n.id,n.x,n.y,n.kind,n.level].join(',')).join(';')+'|'+operatingCompany().edges.map(e=>e.from+e.to).join(';');if(signature!==miniSignature){miniSignature=signature;mini.width=width*dpr;mini.height=height*dpr;miniBackdrop=document.createElement('canvas');miniBackdrop.width=mini.width;miniBackdrop.height=mini.height;let ctx=miniBackdrop.getContext('2d');ctx.scale(dpr,dpr);ctx.fillStyle='#0b1725';ctx.fillRect(0,0,width,height);let left=Math.min(0,...ns.map(n=>n.x-NODE_W/2))-100,right=Math.max(1000,...ns.map(n=>n.x+NODE_W/2))+100,top=Math.min(0,...ns.map(n=>n.y-NODE_H/2))-100,bottom=Math.max(500,...ns.map(n=>n.y+NODE_H/2))+100,scale=Math.min((width-16)/(right-left),(height-24)/(bottom-top)),x=(width-(right-left)*scale)/2-left*scale,y=12+(height-24-(bottom-top)*scale)/2-top*scale;miniTransform={scale,x,y,left,right,top,bottom,width,height};let byId=new Map(ns.map(n=>[n.id,n]));ctx.strokeStyle='#385773';ctx.lineWidth=1;for(let e of operatingCompany().edges){let a=byId.get(e.from),b=byId.get(e.to);if(!a||!b)continue;ctx.beginPath();ctx.moveTo(a.x*scale+x,a.y*scale+y);ctx.lineTo(b.x*scale+x,b.y*scale+y);ctx.stroke();}for(let n of ns){ctx.fillStyle=kindColors[n.kind];ctx.fillRect(n.x*scale+x-Math.max(2,NODE_W*scale/2),n.y*scale+y-Math.max(2,NODE_H*scale/2),Math.max(4,NODE_W*scale),Math.max(4,NODE_H*scale));}ctx.font='8px monospace';ctx.fillStyle='#9cb7ca';ctx.fillText(CITIES[city].label+' · '+ns.length+' NODES',8,10);if(!ns.length){ctx.fillText('NO NETWORK',50,66);}}let m=miniTransform;miniCtx.setTransform(1,0,0,1,0,0);miniCtx.drawImage(miniBackdrop,0,0);miniCtx.setTransform(dpr,0,0,dpr,0,0);let x=(-camera.x/camera.z)*m.scale+m.x,y=(-camera.y/camera.z)*m.scale+m.y,w=W/camera.z*m.scale,h=H/camera.z*m.scale;miniCtx.fillStyle='#5de1ca16';miniCtx.fillRect(x,y,w,h);miniCtx.strokeStyle='#70f4db';miniCtx.lineWidth=1.5;miniCtx.strokeRect(x,y,w,h);}
function miniMove(e){if(!miniTransform||state.finance.loss)return;let r=mini.getBoundingClientRect(),m=miniTransform,x=(e.clientX-r.left)*190/r.width,y=(e.clientY-r.top)*120/r.height,wx=clamp((x-m.x)/m.scale,m.left,m.right),wy=clamp((y-m.y)/m.scale,m.top,m.bottom);camera.x=W/2-wx*camera.z;camera.y=H/2-wy*camera.z;drawMinimap();}
mini.onpointerdown=e=>{e.preventDefault();e.stopPropagation();mini.setPointerCapture(e.pointerId);miniMove(e);};mini.onpointermove=e=>{if(mini.hasPointerCapture(e.pointerId))miniMove(e);};mini.onpointerup=e=>{if(mini.hasPointerCapture(e.pointerId))mini.releasePointerCapture(e.pointerId);};mini.onpointercancel=mini.onpointerup;mini.onkeydown=e=>{let delta={ArrowLeft:[120,0],ArrowRight:[-120,0],ArrowUp:[0,120],ArrowDown:[0,-120]}[e.key];if(!delta)return;e.preventDefault();camera.x+=delta[0];camera.y+=delta[1];drawMinimap();};setMiniOpen(miniOpen);
let accumulator=0,lastTime=0,lastRender=0,lastUI=0,renderSignature='',renderCount=0,renderCosts=[];
function loop(t){let elapsed=lastTime?Math.min(1000,t-lastTime):0;lastTime=t;if(ready&&writer&&!settling&&!offlineBlocked&&!slotBusy&&!paused&&!state.finance.loss&&!document.hidden){accumulator+=elapsed*speed;let steps=0;while(accumulator>=1000&&steps<4&&!state.finance.loss){step(state);state.lastSettledAt=Math.max(state.lastSettledAt,Date.now());checkpointDefense();accumulator-=1000;steps++;emit()}if(steps)updateUI()}if(!document.hidden&&active==='network'&&$('#sheet').hidden&&t-lastRender>=(settings.quality==='low'?32:15)){let signature=[state.tick,topologyVersion,camera.x,camera.y,camera.z,W,H,DPR,selected?.id,connecting,placing,settings.quality,settings.motion,miniOpen].join('|'),animated=settings.motion&&particles.some(p=>p.active);if(signature!==renderSignature||animated){let dt=Math.min(100,t-lastRender),start=performance.now();if(lastRender)frameTimes.push(dt);if(frameTimes.length>180)frameTimes.shift();render(t,dt);drawMinimap();renderSignature=signature;renderCount++;renderCosts.push(performance.now()-start);if(renderCosts.length>180)renderCosts.shift();}lastRender=t;}requestAnimationFrame(loop)}
async function init(){if(navigator.locks){navigator.locks.request(GAME_ID+':writer',{ifAvailable:true},async lock=>{writer=!!lock;if(ready)updateUI();if(lock)await new Promise(resolve=>{window.addEventListener('pagehide',resolve,{once:true})})});await new Promise(r=>setTimeout(r,30));}else{writer=false;toast('탭 잠금을 지원하지 않아 읽기 전용입니다. 다른 최신 브라우저에서 JSON을 가져오세요.')}
try{db=await openDB();let meta=await initializeSlots(db,writer);slotId=meta.active;let slot=await readSlot(db,slotId);slotName=slot.name;let txt=slot.current||await readSave('current');if(txt){try{let s=migrate(JSON.parse(txt));state=s;lastSaved=s.lastSettledAt;toast('저장된 회사를 복원했습니다')}catch{let prev=await readSave('previous');if(!prev)throw Error('손상 저장');let s=migrate(JSON.parse(prev));state=s;toast('이전 정상 세대로 복구했습니다')}}else mobilePositions();}catch(e){console.error(e);offlineBlocked=true;toast('저장을 열 수 없어 진행을 멈췄습니다. 원본은 유지됩니다. 다른 탭을 닫고 새로고침하세요.');mobilePositions();}ready=true;resize();fit();updateUI();await catchUp();setInterval(()=>{if(!document.hidden)save(false)},15000);requestAnimationFrame(loop);}
document.addEventListener('visibilitychange',()=>{if(document.hidden){if(!settling&&!offlineBlocked)save(false);accumulator=0;}else catchUp();lastTime=0});window.addEventListener('pagehide',()=>save(false));
