Object.defineProperty(window,'flowDiagnostics',{get:()=>({version:'0.22.0',state:JSON.parse(JSON.stringify(state)),city,companyId:operatingCompany().id,visibleNodeCount:visibleNodes().length,writer,ready,settling,offlineBlocked,slotId,slotName,slotBusy,lastSaved,speed,paused,camera:{...camera},viewport:{W,H,DPR},renderSamples:frameTimes.slice(),activeParticles:particles.filter(p=>p.active).length,renderCount,renderCosts:renderCosts.slice(),cacheSizes:{tiles:nodeTiles.size,curves:curves.size,badges:badgeCache.size,icons:icons.size},compact:document.body.classList.contains('board-focus')})});
let compactChoice=null;
function syncCompact(){let small=innerWidth<=950,compact=small&&(compactChoice??(innerHeight<700));document.body.classList.toggle('board-focus',compact);$('#focus-toggle').hidden=!small;$('#focus-toggle').textContent=compact?'정보':'집중';$('#focus-toggle').setAttribute('aria-expanded',String(!compact));$('#focus-toggle').setAttribute('aria-label',compact?'경영 정보 펼치기':'경영 정보 접고 보드에 집중');}
