function showHeadquarters(){if(state.tick<HQ_UNLOCK)return toast('본사 경영 허브는3600경제틱(60분)부터 열립니다');selected={type:'hq'};openSheet('HEADQUARTERS',`<div id="hq-content"></div>`);updateHeadquarters(true);}
$('#hq-open').onclick=showHeadquarters;$('#hq-marker').onclick=showHeadquarters;
function updateHeadquarters(force=false){let unlocked=state.tick>=HQ_UNLOCK;$('#hq-open').textContent=unlocked?'본사 경영':'본사 🔒';$('#hq-open').disabled=!unlocked;$('#hq-open').title=unlocked?'무료 경영 허브':'60분·3600경제틱부터';$('#hq-marker').hidden=!unlocked||city!=='hanbit';if(selected?.type!=='hq'||$('#sheet').hidden)return;let d=headquarters(state),root=$('#hq-content');if(!root)return;let sig=JSON.stringify(d);if(!force&&root.dataset.sig===sig)return;root.dataset.sig=sig;let top=$('#sheet-body').scrollTop;root.innerHTML=`<div class="hq-intro"><small>READ-ONLY MANAGEMENT · ${fmt(d.tick)} 경제틱</small><h2>흐름을 읽는 본사</h2><p>60분 해금 · 무료 지원 표시. 건설비·유지비·재고·물류·버프 없음. 생산설비40개 상한과 자산가치에 포함하지 않습니다.</p></div><div class="hq-stats"><article><small>그룹 지분반영 영업이익</small><strong>${fmt(d.profit)} C/틱</strong><span>최근 틱 · 실제 배당/본사 현금 아님</span></article><article><small>최근 ${d.window}/600틱 영업합계</small><strong>${d.window?fmt(d.sum)+' C':'관측 대기'}</strong><span>${d.window<600?'자회사 확보 후600틱이 모여야 안정 목표 판정':'지분율 가중 · 금융거래 제외'}</span></article></div><div class="hq-columns"><section><h3>회사와 지분</h3><p class="muted">현금은 회사별 별도 원장입니다. 연결현금처럼 합치지 않습니다.</p>${d.rows.map(c=>`<article class="hq-company"><div class="row"><b>${esc(c.name)}</b><span>${c.parent?'자회사':'본사'} · ${c.listed?'상장':'비상장'}</span></div><div class="row"><small>회사 현금 / 영업이익</small><strong>${fmt(c.cash)} / ${fmt(c.profit)} C</strong></div><p>${c.parent?'직접 지배 '+esc(c.parent)+' · 직접 '+pct(c.direct)+' · 경제적지분 '+pct(c.weight):'창업자 지분 '+pct(c.founder)}<br>지분반영 영업이익 ${fmt(c.weighted)} C/틱 · 생산설비 ${c.nodes}개</p><div class="hq-actions"><button data-hq-company="${c.id}">공급망 운영</button><button data-hq-equity="${c.id}">지분 상세</button></div></article>`).join('')}<h3>다음 확장 목표</h3>${d.next?`<article class="hq-company"><b>${esc(d.next.name)}</b><p>${esc(d.next.desc)}</p></article>`:'<p>기존 필수 확장 목표를 모두 달성했습니다.</p>'}<p class="muted">센서 선택 목표: ${d.goals.find(g=>g.optional).done?'완료':'미완료'} · 필수 확장을 막지 않습니다.</p><button id="hq-goals" class="full">전체 목표·도움말</button></section><section><h3>인수 위험과 진행</h3>${d.alerts.map(a=>`<article class="hq-risk"><b>${esc(a.name)} · ${a.level}% 경보</b><p>${esc(a.ownerName)} 현재 직접지분 ${pct(a.ratio)} · 대응기한까지 ${a.remaining}틱. 지분50% 초과와 대응기간 경과 시 판정됩니다.</p></article>`).join('')||'<p class="muted">그룹 대상 지분 경보 없음. 안전/방어 성공을 보장하지 않습니다.</p>'}${d.deferred?'<article class="hq-risk"><b>복귀 후 지배권 판정 보류</b><p>금융탭에서 현재 지분과 대응 유예를 확인하세요.</p></article>':''}${d.tenders.map(t=>`<article class="hq-company"><b>${t.incoming?'외부의 그룹 대상 매수':'그룹 관련 매수'}</b><p>${esc(t.owner)} → ${esc(t.target)} · ${t.remaining}틱 남음<br>예약금 ${fmt(t.reserved)} C · 응모/인수 성공 보장 아님</p></article>`).join('')||'<p class="muted">그룹 관련 진행 매수 없음.</p>'}<button id="hq-finance" class="full">금융·지분 방어 열기</button><h3>그룹 기술 공유</h3><p class="muted">완료 기술을 다음 경제틱에 공유합니다. 해금 시점과 구저장 권한은 그대로 적용됩니다. 연구비 환급·본사 버프는 없습니다.</p>${d.rows.map(c=>`<article class="hq-company"><b>${esc(c.name)}</b>${c.tech.map(t=>`<div class="row"><small>${esc(t.name)}</small><span>${t.status}</span></div>`).join('')}${c.research?`<p>${esc(c.research.name)} ${c.research.progress}/${TECHS[c.research.id].points}P</p>`:''}<button data-hq-research="${c.id}" class="full">이 회사 연구 보기</button></article>`).join('')}</section></div>`;$('#sheet-body').scrollTop=top;for(let b of root.querySelectorAll('[data-hq-company]'))b.onclick=()=>hqCompany(b.dataset.hqCompany);for(let b of root.querySelectorAll('[data-hq-equity]'))b.onclick=()=>showEquity(b.dataset.hqEquity);for(let b of root.querySelectorAll('[data-hq-research]'))b.onclick=()=>{hqCompany(b.dataset.hqResearch);showResearch()};$('#hq-goals').onclick=()=>{closeSheet();switchTab('goals')};$('#hq-finance').onclick=()=>{closeSheet();switchTab('finance')};}
function hqCompany(id){companyId=id;city=operatingCompany().cities.includes(city)?city:'hanbit';cancelMode();closeSheet();curves.clear();nodeTiles.clear();particles.forEach(p=>p.active=false);switchTab('network');fit();updateUI();}

function adoptSlot(next,id,name){state=next;slotId=id;slotName=name;companyId='p';city='hanbit';lossShown=false;checkpointKey='';accumulator=0;lastTime=0;selected=null;curves.clear();nodeTiles.clear();particles.forEach(p=>p.active=false);cancelMode();closeSheet();mobilePositions();fit();updateUI();}
async function waitStorage(){while(saveBusy||checkpointBusy)await new Promise(r=>setTimeout(r,10));}
function slotOverlay(){let el=document.createElement('div');el.id='slot-overlay';el.setAttribute('role','status');el.innerHTML='<div><small>SAVE SLOTS</small><h2>슬롯 기록을 보관하는 중</h2><p>저장이 끝나기 전에 화면을 닫지 마세요.<br>대상 슬롯만 최대8시간 복귀 정산합니다.</p><strong id="offline-progress">0%</strong></div>';document.body.append(el);return el;}
async function uniqueCampaign(next,target){for(let id of SLOT_IDS){if(id===target)continue;let slot=await readSlot(db,id);if(slot.current){try{if(JSON.parse(slot.current).campaignId===next.campaignId)throw Error('같은 회사 진행이 이미 '+slot.name+'에 있습니다. 복제 가져오기는 지원하지 않습니다.');}catch(e){if(e.message.includes('복제'))throw e;}}}}
async function replaceActive(next){if(!writer||slotBusy||settling||offlineBlocked)return false;slotBusy=true;await waitStorage();let overlay=slotOverlay();try{validate(next);await uniqueCampaign(next,slotId);let result=next.finance.loss?{state:next,report:null}:await offlineWorker(next,Date.now());await writeSlot(db,slotId,JSON.stringify(result.state),{replace:true,previousText:JSON.stringify(state)});adoptSlot(result.state,slotId,slotName);lastSaved=Date.now();toast(slotName+' 교체 완료');if(result.report)offlineReport();return true;}catch(e){toast('교체 실패 · 현재/원본 유지: '+e.message);return false;}finally{slotBusy=false;overlay.remove();updateUI();}}
async function switchSlot(id){if(!writer||slotBusy||settling||offlineBlocked||id===slotId)return;let wasPaused=paused;paused=true;slotBusy=true;await waitStorage();if(!await save(false,true)){slotBusy=false;paused=wasPaused;return;}let overlay=slotOverlay();try{let target=await readSlot(db,id);if(!target.current)throw Error('빈 슬롯은 먼저 새 회사를 시작하거나 JSON을 가져오세요');let next;try{next=migrate(JSON.parse(target.current));}catch{if(!target.previous)throw Error('대상 저장이 손상되었습니다. JSON으로 보관 후 복구하세요');next=migrate(JSON.parse(target.previous));}let result=next.finance.loss?{state:next,report:null}:await offlineWorker(next,Date.now());await writeSlot(db,id,JSON.stringify(result.state),{activate:true});adoptSlot(result.state,id,target.name);lastSaved=Date.now();toast(target.name+' 선택 완료');if(result.report)offlineReport();}catch(e){toast('슬롯 선택 실패 · 활성 슬롯/대상 원본 유지: '+e.message);}finally{slotBusy=false;paused=wasPaused;overlay.remove();lastTime=0;accumulator=0;updateUI();}}
function exportSlotText(text,name,id){let a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type:'application/json'}));a.href=url;a.download='flow-capital-slot-'+String(id)+'.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function showSlots(){if(!db)return toast('저장소를 열 수 없습니다.');let records=await Promise.all(SLOT_IDS.map(id=>readSlot(db,id)));selected={type:'slots'};openSheet('SAVE SLOTS',`<h2>세 개의 다른 회사 기록</h2><p>현재 <b>${esc(slotName)}</b>. 선택한 슬롯만 온라인 운영·자동 저장합니다. 다른 슬롯을 플레이한 시간도 비운 시간으로 보고, 다시 선택하면 각 슬롯의 실제 경과시간을 최대8시간 정산합니다.</p><p class="muted">이 기기·브라우저에만 보관됩니다. 삭제/데이터 정리는 되돌릴 수 없으니 중요한 기록은 JSON으로 내보내세요. 같은 회사 진행을 다른 슬롯에 복제하지 않습니다.</p><div class="slot-grid">${records.map(r=>{let info=null,bad=false;if(r.current)try{info=migrate(JSON.parse(r.current));}catch{bad=true;}return `<article class="slot-card ${r.id===slotId?'slot-active':''}"><div class="row"><h3>${esc(r.name)}</h3><span class="badge">${r.id===slotId?'현재 선택':r.current?'저장됨':'빈 슬롯'}</span></div><p>${info?`DAY ${Math.floor(info.tick/60)+1} · ${fmt(info.tick)}틱 · 현금 ${fmt(info.player.cash)} C<br>최근 정산 ${esc(new Date(info.lastSettledAt).toLocaleString('ko-KR'))}`:bad?'저장 검증 실패 · 원본 JSON을 보관하세요':'아직 회사 기록이 없습니다.'}</p><div class="slot-actions"><button data-slot-select="${r.id}" ${!writer||!r.current||r.id===slotId?'disabled':''}>선택·복귀 정산</button><button data-slot-new="${r.id}" ${!writer?'disabled':''}>새 회사</button><button data-slot-import="${r.id}" ${!writer?'disabled':''}>가져오기</button><button data-slot-export="${r.id}" ${!r.current?'disabled':''}>JSON 내보내기</button><button data-slot-rename="${r.id}" ${!writer?'disabled':''}>이름 변경</button><button data-slot-delete="${r.id}" class="danger" ${!writer||!r.current||r.id===slotId?'disabled':''}>삭제</button></div></article>`}).join('')}</div><p class="muted">${writer?'슬롯 전환은 현재 기록 저장과 대상 정산 저장에 성공한 뒤에만 완료됩니다. 활성 슬롯은 삭제할 수 없습니다.':'읽기 전용 탭: 내보내기만 가능합니다. 운영 탭을 닫고 새로고침하세요.'}</p>`);for(let b of document.querySelectorAll('[data-slot-select]'))b.onclick=()=>switchSlot(b.dataset.slotSelect);for(let b of document.querySelectorAll('[data-slot-import]'))b.onclick=()=>{if(!writer)return;importTarget=b.dataset.slotImport;$('#import-file').click()};for(let b of document.querySelectorAll('[data-slot-export]'))b.onclick=async()=>{let r=await readSlot(db,b.dataset.slotExport);if(r.current)exportSlotText(r.id===slotId?JSON.stringify(state,null,2):r.current,r.name,r.id)};for(let b of document.querySelectorAll('[data-slot-rename]'))b.onclick=async()=>{if(!writer||slotBusy)return;let r=await readSlot(db,b.dataset.slotRename),name=prompt('슬롯 이름 (1~24자)',r.name);if(name===null)return;try{await renameSlot(db,r.id,name);if(r.id===slotId)slotName=name.trim();updateUI();await showSlots()}catch(e){toast('이름 변경 실패: '+e.message)}};for(let b of document.querySelectorAll('[data-slot-new]'))b.onclick=async()=>{if(!writer||slotBusy)return;let r=await readSlot(db,b.dataset.slotNew);if(!confirm(r.name+'에서 새 회사를 시작할까요? 기존 기록은 이전 세대로 보관됩니다.'))return;if(r.id===slotId){await replaceActive(createGame());return;}if(slotBusy)return;slotBusy=true;try{await waitStorage();if(!await save(false,true))return;await writeSlot(db,r.id,JSON.stringify(createGame()),{replace:true});await showSlots();toast(r.name+' 새 회사 준비 완료 · 선택 버튼으로 운영하세요')}catch(e){toast('새 회사 저장 실패 · 원본 유지: '+e.message)}finally{slotBusy=false;}};for(let b of document.querySelectorAll('[data-slot-delete]'))b.onclick=async()=>{if(!writer||slotBusy)return;let r=await readSlot(db,b.dataset.slotDelete);if(!confirm(r.name+'의 현재·이전·방어 저장을 모두 삭제할까요? 되돌릴 수 없습니다.'))return;slotBusy=true;try{await deleteSlot(db,r.id);await showSlots();toast(r.name+' 삭제 완료')}catch(e){toast('삭제 실패 · 원본 유지: '+e.message)}finally{slotBusy=false;}};}

function foodRecipeText(k){let r=FOOD_RECIPES[k];return (Object.entries(r.inputs).map(([p,q])=>PRODUCTS[p].name+' '+q).join(' + ')||'농장 조달')+' → '+PRODUCTS[r.output].name+' 1 · '+r.cost+' C/개. 공정20% 절감과 별도입니다.';}
function foodBuildSection(){let c=operatingCompany();return '<h2>농장·식품 산업</h2><p>15분부터 농업 기초 → 제분·제빵 / 유가공 / 음료. 원물·밀가루에는 소비자 수요가 없으며 빵·요구르트·포도주스만 매장에서 판매합니다.</p><div class="build-grid">'+Object.entries(FOOD_KINDS).map(([k,v])=>{let r=FOOD_RECIPES[k],locked=!c.research.unlocked.includes(r.tech);return `<button data-food-build="${k}" data-food-product="${r.output}" ${locked||c.cash<v.cost?'disabled':''}><b>${v.name}${locked?' 🔒':''}</b><small>${fmt(v.cost)} C · 유지 ${v.fixed} C/틱</small><small>${foodRecipeText(k)} · ${TECHS[r.tech].name}</small></button>`;}).join('')+'</div><h3>식품 물류·판매</h3><div class="build-grid">'+Object.keys(FOOD_PRODUCTS).flatMap(p=>(FOOD_GOODS.includes(p)?['warehouse','store','port']:['warehouse','port']).map(k=>`<button data-food-build="${k}" data-food-product="${p}" ${!c.research.unlocked.includes(foodTech(p))||c.cash<KINDS[k].cost?'disabled':''}><b>${PRODUCTS[p].name} · ${KINDS[k].name}</b><small>${fmt(KINDS[k].cost)} C</small></button>`)).join('')+'</div>'; }

const B2UI={companies,PRODUCTS,KINDS,CITIES,cityOf,capacity,limit,spend};
